INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (10377, 'Cách tổ chức họp lập bản đồ hành trình khách hàng', 'cach-to-chuc-hop-lap-ban-do-hanh-trinh-khach-hang', '
<p>Lập bản đồ hành trình của khách hàng là một công cụ kinh doanh quan trọng giúp các công ty có được sự hiểu biết toàn diện về các giai đoạn khác nhau mà khách hàng trải qua khi hoàn thành một nhiệm vụ. Nó cũng đi sâu vào những cảm xúc và suy nghĩ mà họ gặp phải trong suốt hành trình của mình.</p>



<p>Bằng cách trực quan hóa và phân tích quy trình này, doanh nghiệp có thể xác định chính xác các điểm yếu trong trải nghiệm của khách hàng và chủ động thực hiện các biện pháp để giải quyết chúng.</p>



<p>Trong bài đăng này, tôi trình bày hướng dẫn từng bước để tiến hành thành công cuộc họp Lập bản đồ hành trình khách hàng.</p>



<h2 class="wp-block-heading">Lập kế hoạch cuộc họp lập bản đồ hành trình khách hàng</h2>



<h3 class="wp-block-heading">1. Đặt mục tiêu cuộc họp</h3>



<p>Chìa khóa cho một cuộc họp thành công là hiểu rõ mục tiêu của nó. Nếu không có các mục tiêu được xác định rõ ràng, kết quả có thể trở nên không rõ ràng. Dưới đây là các yếu tố cần xác nhận trước cuộc họp:</p>



<h4 class="wp-block-heading">Quyết định (những) Persona nào để lập bản đồ</h4>



<p>Bản đồ hành trình của khách hàng được gắn chặt với chân dung khách hàng. Trước cuộc họp, điều quan trọng là phải xác định cá tính hoặc cá tính của khách hàng sẽ là trọng tâm của quy trình lập bản đồ.</p>



<p><strong>Tìm hiểu thêm</strong>: <a href="https://huynhhieutravel.com/chan-dung-khach-hang/" target="_blank" rel="noreferrer noopener">Cách tạo Chân dung người dùng Persona cho doanh nghiệp</a>.</p>



<figure class="wp-block-image size-full is-resized"><img loading="lazy" decoding="async" src="https://media.huynhhieutravel.com/vi-du-chan-dung-khach-hang.webp" alt="Ví dụ về Chân dung khách hàng" class="wp-image-10381" width="500" height="387" srcset="https://media.huynhhieutravel.com/vi-du-chan-dung-khach-hang.webp 1000w, https://media.huynhhieutravel.com/vi-du-chan-dung-khach-hang-768x594.webp 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption class="wp-element-caption">Ví dụ về Chân dung khách hàng</figcaption></figure>



<h4 class="wp-block-heading">Quyết định loại bản đồ hành trình bạn muốn tạo</h4>



<p>Có 3 loại bản đồ hành trình khách hàng chính:</p>



<ol class="wp-block-list">
<li><strong>Bản đồ hành trình của khách hàng:</strong> Ghi lại toàn bộ hành trình của khách hàng, từ nhận thức đến bán hàng, giao hàng và dịch vụ.</li>



<li><strong>Bản đồ hành trình của người dùng:</strong> Tập trung vào việc hiểu cách người dùng tương tác với phần mềm để xác định các khía cạnh trực quan và thách thức.</li>



<li><strong>Bản đồ hành trình của người mua:</strong> Hỗ trợ nhóm bán hàng và tiếp thị lập bản đồ lộ trình của khách hàng trước khi trở thành khách hàng.</li>
</ol>



<figure class="wp-block-image size-full is-resized"><img loading="lazy" decoding="async" src="https://media.huynhhieutravel.com/vi-du-ve-ban-do-hanh-trinh-nguoi-mua.webp" alt="Ví dụ về bản đồ hành trình của người mua" class="wp-image-10382" width="855" height="482" srcset="https://media.huynhhieutravel.com/vi-du-ve-ban-do-hanh-trinh-nguoi-mua.webp 1140w, https://media.huynhhieutravel.com/vi-du-ve-ban-do-hanh-trinh-nguoi-mua-768x433.webp 768w" sizes="(max-width: 855px) 100vw, 855px" /><figcaption class="wp-element-caption">Ví dụ về bản đồ hành trình của người mua</figcaption></figure>



<p>Trong giai đoạn lập kế hoạch cuộc họp, hãy quyết định rõ ràng về loại bản đồ mà những người tham gia sẽ xây dựng. Xác định các điểm cuối của bản đồ, chẳng hạn như điểm mà Bản đồ hành trình của người mua dừng lại, chẳng hạn như &#8220;khi khách hàng đặt hàng&#8221;.</p>



<h4 class="wp-block-heading">Bản đồ Hiện trạng so với Bản đồ Nên là</h4>



<p>Xác định xem bạn sẽ lập bản đồ hành trình của khách hàng hiện tại (bản đồ Hiện trạng) hay hành trình mong muốn (bản đồ Nên-Trở thành). Thông thường, ánh xạ hành trình Như hiện có trước khi cải thiện nó bằng hành trình Nên-Trở thành. Đối với bản đồ lần đầu tiên, hãy cân nhắc tập trung vào hành trình Như-Là.</p>



<h3 class="wp-block-heading">2. Chọn người tham dự cuộc họp lập bản đồ hành trình</h3>



<p>Mặc dù không có quy tắc nghiêm ngặt nào để chọn người tham dự, hãy xem xét các nguyên tắc sau:</p>



<h4 class="wp-block-heading">Bao gồm các đại diện đa chức năng</h4>



<p>Mời những người tham gia từ các bộ phận khác nhau trong toàn doanh nghiệp để đảm bảo có nhiều quan điểm về hành trình của khách hàng. Đại diện đa dạng này mang lại thông tin chính xác và mua vào đa dạng.</p>



<h4 class="wp-block-heading">Số người tham dự</h4>



<p>Tạo sự cân bằng với số lượng người tham dự. Quá ít người có thể thiếu kiến ​​thức cần thiết và quá nhiều người có thể khiến cuộc họp trở nên khó sử dụng. Phạm vi 5-8 người thường hoạt động tốt cho hầu hết các cuộc họp.</p>



<h4 class="wp-block-heading">Thâm niên của người tham dự</h4>



<p>Chọn những người tham dự tham gia chặt chẽ vào các hoạt động thực tế thay vì chỉ các chính sách của công ty. Các nhà quản lý cấp cao có thể bị ngắt kết nối khỏi các hoạt động hàng ngày, vì vậy sự hiện diện của họ có thể cản trở cuộc thảo luận cởi mở.</p>



<h3 class="wp-block-heading">3. Người hướng dẫn bên ngoài hay bên trong?</h3>



<p>Một Người hướng dẫn lành nghề là điều cần thiết cho sự thành công của cuộc họp. Họ không cần phải là chuyên gia trong lĩnh vực kinh doanh mà nên tập trung vào chính quy trình cuộc họp.</p>



<p>Một người hỗ trợ bên ngoài, có kinh nghiệm trong cả việc hỗ trợ và lập bản đồ hành trình, có thể nâng cao hiệu quả và thành công của cuộc họp</p>



<h3 class="wp-block-heading">4. Người tham dự trước khi làm việc</h3>



<p>Chọn những người tham dự hiểu rõ về doanh nghiệp, giảm thiểu nhu cầu chuẩn bị. Tuy nhiên, hãy yêu cầu họ mang theo bất kỳ tài liệu liên quan hoặc nghiên cứu khách hàng nào có thể hỗ trợ cuộc họp.</p>



<h3 class="wp-block-heading">5. Thời lượng cuộc họp</h3>



<p>Lên kế hoạch cho các buổi họp kéo dài 4 giờ với thời gian nghỉ giải lao 15 phút. Cân nhắc chỉ đăng ký một cuộc họp mỗi ngày để giảm bớt phiền nhiễu và cho phép người tham dự quản lý các nhiệm vụ thường xuyên của họ.</p>



<p>Bằng cách lập kế hoạch tỉ mỉ cho từng khía cạnh, cuộc họp Lập bản đồ hành trình của khách hàng có thể được cấu trúc để thành công, đảm bảo kết quả rõ ràng, hiệu quả và có ý nghĩa.</p>



<h2 class="wp-block-heading">Điều hành cuộc họp Bản đồ Hành trình</h2>



<p>Bây giờ, việc lập kế hoạch đã hoàn tất, đã đến lúc thực hiện cuộc họp lập bản đồ hành trình. Dưới đây là hướng dẫn về cách điều hành cuộc họp hiệu quả:</p>



<h3 class="wp-block-heading">Bắt đầu với phần giới thiệu quản lý cấp cao</h3>



<p>Nếu có thể, hãy bắt đầu cuộc họp với 1 người quản lý cấp cao giới thiệu phiên họp. Điều này giúp thiết lập bối cảnh, làm nổi bật tầm quan trọng của việc lập bản đồ hành trình và giá trị của nó đối với những người tham dự.</p>



<h3 class="wp-block-heading">Giới thiệu người hướng dẫn và mục tiêu cuộc họp</h3>



<p>Sau đó, Người hướng dẫn nên phác thảo các mục tiêu của cuộc họp cho những người tham gia. Chia sẻ các tài liệu lập kế hoạch, bao gồm các mục tiêu, cá nhân và quy trình của cuộc họp.</p>



<h3 class="wp-block-heading">Tạo bản đồ hành trình của khách hàng</h3>



<p>Thông báo cho những người tham gia về kết quả mong muốn, cung cấp một bản đồ ví dụ và giải thích cách bản đồ sẽ được phát triển.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1024" height="572" src="https://media.huynhhieutravel.com/vi-de-ve-ban-do-hanh-trinh-khach-hang-1024x572.jpeg" alt="Ví dụ về Bản đồ hành trình khách hàng" class="wp-image-10383"/><figcaption class="wp-element-caption">Ví dụ về Bản đồ hành trình khách hàng</figcaption></figure>



<p>Có hai phương pháp chính để tạo bản đồ:</p>



<h4 class="wp-block-heading">1. Tạo Bản đồ hành trình của khách hàng thực</h4>



<p>Nếu tất cả những người tham gia đều ở cùng một địa điểm, việc sử dụng giấy ghi chú và giấy bán thịt có thể hiệu quả. Thực hiện theo các bước sau:</p>



<ul class="wp-block-list">
<li>Phân phát các ghi chú dán lớn (khoảng 3”x 5”) cho mỗi người tham dự.</li>



<li>Hướng dẫn người tham dự viết ra các điểm tiếp xúc riêng lẻ tồn tại trong hành trình của khách hàng. Ghi chú phải rõ ràng, súc tích (tối đa 5 từ) và bằng chữ viết tay dễ đọc.</li>



<li>Chuẩn bị các tờ giấy bảng lật trên tường, vẽ một đường ngang ở giữa. Gắn nhãn nửa trên là &#8220;Khách hàng&#8221; và nửa dưới là &#8220;Công ty&#8221;. Đánh dấu &#8220;Bắt đầu&#8221; ở trên cùng bên trái và &#8220;Kết thúc&#8221; ở trên cùng.</li>



<li>Người tham gia nên đặt ghi chú điểm tiếp xúc của họ trên bản đồ trong các phần thích hợp (do khách hàng khởi xướng hoặc do công ty khởi tạo). Khuyến khích sắp xếp lại để đảm bảo đúng thứ tự.</li>



<li>Bắt đầu ở trên cùng bên trái và làm việc trên bản đồ một cách tương tác, thảo luận về hành trình từng bước một.</li>



<li>Tạo ghi chú dán mới cho những điểm tiếp xúc bị lãng quên và giải quyết những bất đồng để tạo ra một bản đồ hành trình gắn kết.</li>
</ul>



<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="768" height="1024" src="https://media.huynhhieutravel.com/hanh-trinh-khach-hang-se-kha-lon-xon-trong-cuoc-hop.jpg" alt="Đôi khi hành trình khách hàng vật lý nhìn sẽ khá lộn xộn" class="wp-image-10384"/><figcaption class="wp-element-caption">Đôi khi hành trình khách hàng vật lý nhìn sẽ khá lộn xộn</figcaption></figure>



<h4 class="wp-block-heading">2. Tạo bản đồ kỹ thuật số</h4>



<p>Nhiều công cụ phần mềm lập bản đồ hành trình của khách hàng có sẵn để ghi lại bản đồ. Nếu những người tham gia ở xa, cuộc họp ảo có thể hiệu quả khi sử dụng các công cụ này. Quá trình này tương tự như cách tiếp cận vật lý:</p>



<ul class="wp-block-list">
<li>Người tham gia sử dụng ghi chú ảo trong phần mềm để mô phỏng các ghi chú vật lý.</li>



<li>Một số công cụ, chẳng hạn như Miro, cho phép tất cả những người tham gia đóng góp ảo, tự động thêm các ghi chú dán của họ vào một không gian chung.</li>
</ul>



<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="1280" height="946" src="https://media.huynhhieutravel.com/template-ban-do-hanh-trinh-khach-hang-cua-miro.jpg" alt="Template bản đồ hành trình khách hàng của Miro" class="wp-image-10385" srcset="https://media.huynhhieutravel.com/template-ban-do-hanh-trinh-khach-hang-cua-miro.jpg 1280w, https://media.huynhhieutravel.com/template-ban-do-hanh-trinh-khach-hang-cua-miro-768x568.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption class="wp-element-caption">Template bản đồ hành trình khách hàng của Miro</figcaption></figure>



<p>Tuy nhiên, hãy đảm bảo rằng Người hướng dẫn sử dụng thành thạo phần mềm để tránh nhầm lẫn.</p>



<p>Bằng cách làm theo các bước này, bạn có thể dẫn dắt cuộc họp lập bản đồ hành trình khách hàng thành công, dẫn đến một bản đồ toàn diện và chính xác về trải nghiệm của khách hàng.</p>



<h2 class="wp-block-heading">Các bước họp lập bản đồ sau hành trình</h2>



<p>Hoàn thành cuộc họp lập bản đồ hành trình không phải là đích đến cuối cùng; đó là một bước để đạt được mục tiêu của bạn. Sau khi cuộc họp kết thúc, đây là những gì bạn nên làm tiếp theo:</p>



<h3 class="wp-block-heading">1. Tài liệu và chia sẻ bản đồ</h3>



<p>Chia sẻ kết quả của cuộc họp là rất quan trọng, giống như bất kỳ nỗ lực hợp tác nào khác. Vì bản đồ hành trình là một tài liệu sống nên việc lưu hành nó trong tổ chức của bạn thậm chí còn cần thiết hơn. Nếu bạn đã sử dụng các tài liệu vật lý như giấy và ghi chú dán, điều quan trọng là phải chuyển nội dung vào phần mềm lập bản đồ hành trình để dễ dàng cập nhật và chia sẻ.</p>



<p>Phân phối các tập tin cho những người tham dự và các bộ phận có liên quan khác. Đảm bảo bản đồ có thể truy cập được đối với những người có thể hưởng lợi từ thông tin chi tiết mà bản đồ cung cấp.</p>



<h3 class="wp-block-heading">2. Xác thực bản đồ hành trình</h3>



<p>Trong cuộc họp, bạn có thể đã đưa ra các giả định do thông tin không đầy đủ hoặc các lĩnh vực cần nghiên cứu thêm. Điều cần thiết là xác nhận những giả định này sau cuộc họp.</p>



<p>Hoàn thành bất kỳ nghiên cứu nổi bật nào hoặc thu thập dữ liệu cần thiết sẽ đảm bảo tính chính xác và độ tin cậy của bản đồ. Một bản đồ chính xác sẽ là nền tảng cho các phân tích có ý nghĩa và các hành động trong tương lai.</p>



<h3 class="wp-block-heading">3. Phân tích bản đồ và hành động</h3>



<p>Cuối cùng, mục đích của tất cả nỗ lực này là sử dụng bản đồ hành trình để xác định các cơ hội cải thiện hoạt động kinh doanh của bạn.</p>



<p>Phân tích bản đồ để xác định các điểm yếu, lỗ hổng và các lĩnh vực cần nâng cao tiềm năng trong hành trình của khách hàng. Tìm kiếm các mẫu và xu hướng có thể tiết lộ các lĩnh vực cần cải tiến hoặc đổi mới.</p>



<p>Dựa trên những hiểu biết sâu sắc này, hãy phát triển các kế hoạch hành động giải quyết các cơ hội đã xác định. Phân công trách nhiệm thực hiện các hành động này cho các thành viên trong nhóm có liên quan. Đây là nơi diễn ra quá trình chuyển đổi thực sự, sử dụng bản đồ làm hướng dẫn để nâng cao trải nghiệm của khách hàng và tối ưu hóa quy trình kinh doanh của bạn.</p>



<p>Bằng cách làm theo các bước này, bạn có thể trích xuất những hiểu biết có giá trị từ bản đồ hành trình và biến chúng thành các chiến lược khả thi nhằm thúc đẩy sự thay đổi tích cực trong tổ chức của bạn.</p>
